FILE* open_file_read(const char* filepath) {
    FILE* f = fopen(filepath, "r");
    return f;
}

int read_file_lines(const char* path, char lines[][256], int max_lines) {
    FILE* f = fopen(path, "r");
    if (!f) return -1;
    int count = 0;
    while (count < max_lines && fgets(lines[count], 256, f) != NULL) {
        lines[count][strcspn(lines[count], "\n")] = '\0';
        count++;
    }
    fclose(f);
    return count;
}

int write_file_text(const char* path, const char* text) {
    FILE* f = fopen(path, "w");
    if (!f) return -1;
    fputs(text, f);
    fclose(f);
    return 0;
}

int append_file_text(const char* path, const char* text) {
    FILE* f = fopen(path, "a");
    if (!f) return -1;
    fputs(text, f);
    fclose(f);
    return 0;
}

size_t write_binary_records(const char* path, const void* records, size_t size, size_t count) {
    FILE* f = fopen(path, "wb");
    if (!f) return 0;
    size_t written = fwrite(records, size, count, f);
    fclose(f);
    return written;
}

