#include <stdio.h>
#include <stdlib.h>

int main(void) {
    size_t n = 5;
    int* data = (int*)malloc(n * sizeof(int));
    if (!data) return 1;

    for (size_t i = 0; i < n; i++) {
        data[i] = (int)((i + 1) * 15);
    }

    long long sum = 0;
    int min_val = data[0];
    int max_val = data[0];
    for (size_t i = 0; i < n; i++) {
        sum += data[i];
        if (data[i] < min_val) min_val = data[i];
        if (data[i] > max_val) max_val = data[i];
    }

    printf("Count: %zu, Sum: %lld, Average: %.2f, Min: %d, Max: %d\n",
           n, sum, (double)sum / n, min_val, max_val);

    free(data);
    data = NULL;
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    size_t cap = 2;
    size_t count = 0;
    int* buffer = (int*)malloc(cap * sizeof(int));
    if (!buffer) return 1;

    for (int val = 10; val <= 60; val += 10) {
        if (count >= cap) {
            cap *= 2;
            int* next = (int*)realloc(buffer, cap * sizeof(int));
            if (!next) {
                free(buffer);
                return 1;
            }
            buffer = next;
        }
        buffer[count++] = val;
    }

    printf("Dynamic buffer (capacity %zu, count %zu):\n", cap, count);
    for (size_t i = 0; i < count; i++) {
        printf("%d ", buffer[i]);
    }
    putchar('\n');

    free(buffer);
    return 0;
}

