int str_words(const char* s) {
    int count = 0, in_word = 0;
    for (int i = 0; s[i] != '\0'; i++) {
        if (s[i] == ' ' || s[i] == '\t' || s[i] == '\n') in_word = 0;
        else if (!in_word) { in_word = 1; count++; }
    }
    return count;
}

