int linear_queue_enqueue(LinearQueue* q, int val) {
    if (q->rear >= q->capacity - 1) return 0;
    q->data[++q->rear] = val;
    return 1;
}

int linear_queue_dequeue(LinearQueue* q, int* val) {
    if (q->front > q->rear) return 0;
    *val = q->data[q->front++];
