int segtree_query_range(const SegTree* st, int l, int r) {
    int sum = 0;
    int n = st->n;
    for (l += n, r += n + 1; l < r; l >>= 1, r >>= 1) {
        if (l & 1) sum += st->tree[l++];
        if (r & 1) sum += st->tree[--r];
    }
    return sum;
}

