}

void dc_insert_beginning(Node** head, int data) {
    Node* n = (Node*)malloc(sizeof(Node));
    if (!n) return;
    n->data = data;
    if (!*head) {
        n->next = n;
        n->prev = n;
        *head = n;
        return;
    }
    Node* last = (*head)->prev;
    n->next = *head;
    n->prev = last;
    last->next = n;
    (*head)->prev = n;
    *head = n;
}

int dc_insert_at_position(Node** head, int pos, int data) {
    if (pos < 1) return 0;
    if (pos == 1) {
        dc_insert_beginning(head, data);
        return 1;
    }
    if (!*head) return 0;
    Node* cur = *head;
    for (int i = 1; cur->next != *head && i < pos - 1; i++) cur = cur->next;
    Node* n = (Node*)malloc(sizeof(Node));
    if (!n) return 0;
    n->data = data;
    n->next = cur->next;
    n->prev = cur;
    cur->next->prev = n;
    cur->next = n;
    return 1;
}

int dc_insert_before(Node** head, int target, int data) {
    if (!head || !*head) return 0;
    if ((*head)->data == target) {
        dc_insert_beginning(head, data);
        return 1;
    }
    Node* cur = (*head)->next;
    while (cur != *head && cur->data != target) cur = cur->next;
    if (cur != *head) {
        Node* n = (Node*)malloc(sizeof(Node));
        if (!n) return 0;
        n->data = data;
        n->prev = cur->prev;
        n->next = cur;
        cur->prev->next = n;
        cur->prev = n;
        return 1;
    }
    return 0;
}

int dc_insert_after(Node* head, int target, int data) {
    if (!head) return 0;
    Node* cur = head;
    do {
        if (cur->data == target) {
            Node* n = (Node*)malloc(sizeof(Node));
            if (!n) return 0;
            n->data = data;
            n->next = cur->next;
            n->prev = cur;
            cur->next->prev = n;
            cur->next = n;
            return 1;
        }
        cur = cur->next;
    } while (cur != head);
    return 0;
}

void dc_insert_sorted(Node** head, int data) {
    Node* n = (Node*)malloc(sizeof(Node));
    if (!n) return;
    n->data = data;
    if (!*head) {
        n->next = n;
        n->prev = n;
        *head = n;
        return;
    }
    if (data <= (*head)->data) {
        Node* last = (*head)->prev;
        n->next = *head;
        n->prev = last;
        last->next = n;
        (*head)->prev = n;
        *head = n;
        return;
    }
    Node* cur = *head;
    while (cur->next != *head && cur->next->data < data) cur = cur->next;
    n->next = cur->next;
    n->prev = cur;
    cur->next->prev = n;
    cur->next = n;
}

int dc_delete_beginning(Node** head, int* val) {
