void dc_reverse(Node** head) {
    if (!head || !*head || (*head)->next == *head) return;
    Node* cur = *head;
    do {
        Node* tmp = cur->next;
        cur->next = cur->prev;
        cur->prev = tmp;
        cur = tmp;
    } while (cur != *head);
    *head = (*head)->prev;
}

void dc_sort(Node* head) {
    if (!head || head->next == head) return;
    int swapped;
    do {
        swapped = 0;
        Node* cur = head;
        while (cur->next != head) {
            if (cur->data > cur->next->data) {
                int tmp = cur->data;
                cur->data = cur->next->data;
                cur->next->data = tmp;
                swapped = 1;
            }
            cur = cur->next;
        }
    } while (swapped);
}

void dc_remove_duplicates(Node* head) {
    if (!head || head->next == head) return;
    Node* cur = head;
    do {
        Node* runner = cur->next;
        while (runner != head) {
            if (runner->data == cur->data) {
                Node* del = runner;
                runner = runner->next;
                del->prev->next = del->next;
                del->next->prev = del->prev;
                free(del);
            } else {
                runner = runner->next;
            }
        }
        cur = cur->next;
    } while (cur != head && cur->next != head);
}

int dc_find_middle(const Node* head, int* val) {
