void bst_morris_inorder(Node* root) {
    Node* cur = root;
    while (cur) {
        if (!cur->left) {
            printf("%d ", cur->data);
            cur = cur->right;
        } else {
            Node* prev = cur->left;
            while (prev->right && prev->right != cur) prev = prev->right;
            if (!prev->right) {
                prev->right = cur;
                cur = cur->left;
            } else {
                prev->right = NULL;
                printf("%d ", cur->data);
                cur = cur->right;
            }
        }
    }
}

