static Node* bst_find_min_internal(Node* root) {
    while (root && root->left) root = root->left;
    return root;
}

Node* bst_delete(Node* root, int val) {
    if (!root) return NULL;
    if (val < root->data) {
        root->left = bst_delete(root->left, val);
    } else if (val > root->data) {
        root->right = bst_delete(root->right, val);
    } else {
        if (!root->left) {
            Node* tmp = root->right;
            free(root);
            return tmp;
        } else if (!root->right) {
            Node* tmp = root->left;
            free(root);
            return tmp;
        }
        Node* succ = bst_find_min_internal(root->right);
        root->data = succ->data;
        root->right = bst_delete(root->right, succ->data);
    }
    return root;
}

Node* bst_find_min(Node* root) {
    while (root && root->left) root = root->left;
    return root;
}

Node* bst_find_max(Node* root) {
    while (root && root->right) root = root->right;
    return root;
}

int bst_height(const Node* root) {
    if (!root) return 0;
    int lh = bst_height(root->left);
    int rh = bst_height(root->right);
    return (lh > rh ? lh : rh) + 1;
}

int bst_count_nodes(const Node* root) {
    if (!root) return 0;
    return 1 + bst_count_nodes(root->left) + bst_count_nodes(root->right);
}

int bst_leaf_count(const Node* root) {
