    free(cur);
    return true;
}

bool delete_at_position(Node** head, int pos, int* val) {
    if (!*head || pos < 1) return false;
    if (pos == 1) return delete_beginning(head, val);
    Node* cur = *head;
    for (int i = 1; cur && i < pos; i++) cur = cur->next;
    if (!cur) return false;
    *val = cur->data;
    if (cur->prev) cur->prev->next = cur->next;
    if (cur->next) cur->next->prev = cur->prev;
    free(cur);
    return true;
}

bool delete_by_value(Node** head, int val) {
    if (!*head) return false;
    Node* cur = *head;
    while (cur && cur->data != val) cur = cur->next;
    if (!cur) return false;
    if (cur == *head) *head = cur->next;
    if (cur->prev) cur->prev->next = cur->next;
    if (cur->next) cur->next->prev = cur->prev;
    free(cur);
    return true;
}

bool delete_after_value(Node* head, int target, int* val) {
    Node* cur = head;
    while (cur && cur->data != target) cur = cur->next;
    if (!cur || !cur->next) return false;
    Node* del = cur->next;
    *val = del->data;
    cur->next = del->next;
    if (del->next) del->next->prev = cur;
    free(del);
    return true;
}

int search_element(const Node* head, int val) {
    const Node* cur = head;
    int pos = 1;
    while (cur) {
        if (cur->data == val) return pos;
        cur = cur->next;
        pos++;
    }
    return -1;
}

void display_forward(const Node* head) {
    if (!head) {
        printf("List is empty.\n");
        return;
    }
    printf("Forward: ");
    const Node* cur = head;
    while (cur) {
        printf("%d <-> ", cur->data);
        cur = cur->next;
    }
    printf("NULL\n");
}

void display_backward(const Node* head) {
    if (!head) {
        printf("List is empty.\n");
        return;
    }
    const Node* cur = head;
    while (cur->next) cur = cur->next;
    printf("Backward: ");
    while (cur) {
        printf("%d <-> ", cur->data);
        cur = cur->prev;
    }
    printf("NULL\n");
}

void reverse_list(Node** head) {
    if (!*head) return;
    Node* cur = *head;
    Node* tmp = NULL;
    while (cur) {
        tmp = cur->prev;
        cur->prev = cur->next;
        cur->next = tmp;
        cur = cur->prev;
    }
    if (tmp) *head = tmp->prev;
}

void sort_list(Node* head) {
    if (!head || !head->next) return;
    int swapped;
    do {
        swapped = 0;
        Node* cur = head;
        while (cur->next) {
            if (cur->data > cur->next->data) {
                int t = cur->data;
                cur->data = cur->next->data;
                cur->next->data = t;
                swapped = 1;
            }
            cur = cur->next;
        }
    } while (swapped);
}

void remove_duplicates(Node* head) {
    Node* cur = head;
    while (cur && cur->next) {
        Node* runner = cur->next;
        while (runner) {
            if (runner->data == cur->data) {
                Node* del = runner;
                runner = runner->next;
                if (del->prev) del->prev->next = del->next;
                if (del->next) del->next->prev = del->prev;
                free(del);
            } else {
                runner = runner->next;
            }
        }
        cur = cur->next;
    }
}

bool find_middle(const Node* head, int* val) {
    if (!head) return false;
    const Node* slow = head;
    const Node* fast = head;
    while (fast->next && fast->next->next) {
        slow = slow->next;
        fast = fast->next->next;
    }
    *val = slow->data;
    return true;
}

bool min_and_max(const Node* head, int* min_val, int* max_val) {
    if (!head) return false;
    *min_val = head->data;
    *max_val = head->data;
    const Node* cur = head->next;
    while (cur) {
        if (cur->data < *min_val) *min_val = cur->data;
        if (cur->data > *max_val) *max_val = cur->data;
        cur = cur->next;
    }
    return true;
}

void free_list(Node** head) {
    Node* cur = *head;
    while (cur) {
        Node* nxt = cur->next;
        free(cur);
        cur = nxt;
    }
    *head = NULL;
}

