}

typedef struct StackNode {
    int data;
    struct StackNode* next;
} StackNode;

void ls_push(StackNode** top, int val) {
    StackNode* n = (StackNode*)malloc(sizeof(StackNode));
    n->data = val;
    n->next = *top;
    *top = n;
}

bool ls_pop(StackNode** top, int* val) {
    if (!*top) return false;
    StackNode* tmp = *top;
    *val = tmp->data;
    *top = (*top)->next;
    free(tmp);
    return true;
}

bool ls_peek(const StackNode* top, int* val) {
    if (!top) return false;
    *val = top->data;
    return true;
}

int ls_count(const StackNode* top) {
    int cnt = 0;
    while (top) { cnt++; top = top->next; }
    return cnt;
}

void ls_display(const StackNode* top) {
    if (!top) { printf("Linked Stack is empty.\n"); return; }
    printf("Linked Stack [top to bottom]: ");
    while (top) {
        printf("%d -> ", top->data);
        top = top->next;
    }
    printf("NULL\n");
}

void ls_free(StackNode** top) {
    while (*top) {
        StackNode* tmp = *top;
        *top = (*top)->next;
        free(tmp);
    }
}

int main(void) {
    StackNode* top = NULL;
