                printf("Enter two elements (0 to %d): ", n - 1);
                if (scanf("%d %d", &u, &v) == 2 && u >= 0 && u < n && v >= 0 && v < n) {
                    union_by_rank(dsu, u, v);
                    printf("Union by rank applied to %d and %d.\n", u, v);
                } else clear_input();
                break;
            case 2:
                printf("Enter two elements (0 to %d): ", n - 1);
                if (scanf("%d %d", &u, &v) == 2 && u >= 0 && u < n && v >= 0 && v < n) {
                    union_by_size(dsu, u, v);
