                } else clear_input();
                break;
            case 3:
                printf("Enter element (0 to %d): ", n - 1);
                if (scanf("%d", &u) == 1 && u >= 0 && u < n) {
                    printf("Representative of %d is: %d\n", u, find_rep(dsu, u));
                } else clear_input();
                break;
            case 4:
