unsigned long hash_djb2(const char* str) {
    unsigned long hash = 5381;
    int c;
    while ((c = (unsigned char)*str++)) {
        hash = ((hash << 5) + hash) + c;
    }
    return hash;
}

uint32_t hash_fnv1a(const char* str) {
    uint32_t hash = 2166136261u;
    while (*str) {
        hash ^= (uint8_t)(*str++);
        hash *= 16777619u;
    }
    return hash;
}

uint32_t hash_murmur32(const char* key, uint32_t seed) {
    uint32_t h = seed;
    uint32_t k;
    size_t len = strlen(key);
    const uint8_t* data = (const uint8_t*)key;
    const size_t nblocks = len / 4;

    for (size_t i = 0; i < nblocks; i++) {
        k = (uint32_t)data[i*4] | ((uint32_t)data[i*4+1] << 8) |
            ((uint32_t)data[i*4+2] << 16) | ((uint32_t)data[i*4+3] << 24);
        k *= 0xcc9e2d51;
        k = (k << 15) | (k >> 17);
        k *= 0x1b873593;
        h ^= k;
        h = (h << 13) | (h >> 19);
        h = h * 5 + 0xe6546b64;
    }

    k = 0;
    const uint8_t* tail = data + (nblocks * 4);
    switch (len & 3) {
        case 3: k ^= (uint32_t)tail[2] << 16;
        case 2: k ^= (uint32_t)tail[1] << 8;
        case 1: k ^= (uint32_t)tail[0];
                k *= 0xcc9e2d51;
                k = (k << 15) | (k >> 17);
                k *= 0x1b873593;
                h ^= k;
    }

    h ^= (uint32_t)len;
    h ^= h >> 16;
    h *= 0x85ebca6b;
    h ^= h >> 13;
    h *= 0xc2b2ae35;
    h ^= h >> 16;
    return h;
}

unsigned long hash_sdbm(const char* str) {
    unsigned long hash = 0;
    int c;
    while ((c = (unsigned char)*str++)) {
        hash = c + (hash << 6) + (hash << 16) - hash;
    }
    return hash;
}

uint64_t hash_polynomial(const char* str) {
    const int p = 31;
    const uint64_t m = 1000000009;
    uint64_t hash_val = 0;
    uint64_t p_pow = 1;
    while (*str) {
        hash_val = (hash_val + (*str - 'a' + 1) * p_pow) % m;
        p_pow = (p_pow * p) % m;
        str++;
    }
    return hash_val;
}

static int count_differing_bits(uint32_t a, uint32_t b) {
    uint32_t diff = a ^ b;
    int cnt = 0;
    while (diff) {
        cnt += diff & 1;
        diff >>= 1;
    }
    return cnt;
}

