#include <stdio.h>

int lower_bound(const int* arr, int n, int target) {
    int l = 0, h = n;
    while (l < h) {
        int m = l + (h - l) / 2;
        if (arr[m] >= target) h = m;
        else l = m + 1;
    }
    return l;
}

