int two_sum(const int* arr, int n, int target, int* out_l, int* out_r) {
    int l = 0, r = n - 1;
    while (l < r) {
        int sum = arr[l] + arr[r];
        if (sum == target) {
            *out_l = l; *out_r = r;
            return 1;
        }
        if (sum < target) l++;
        else r--;
    }
    return 0;
}

