#define N 4

int solve_maze(int maze[N][N], int x, int y, int sol[N][N]) {
    if (x == N - 1 && y == N - 1 && maze[x][y] == 1) {
        sol[x][y] = 1;
        return 1;
    }
    if (x >= 0 && x < N && y >= 0 && y < N && maze[x][y] == 1) {
        if (sol[x][y]) return 0;
        sol[x][y] = 1;
        if (solve_maze(maze, x + 1, y, sol)) return 1;
        if (solve_maze(maze, x, y + 1, sol)) return 1;
        sol[x][y] = 0;
        return 0;
    }
    return 0;
}

