    if (c == '-') {
        sign = -1;
        c = getchar();
    }
    long long res = 0;
    while (c >= '0' && c <= '9') {
        res = res * 10 + (c - '0');
        c = getchar();
    }
    *out_val = res * sign;
    return 1;
}

int cp_coordinate_compress(int* arr, int n, int* unique_arr) {
    for (int i = 0; i < n; i++) {
        unique_arr[i] = arr[i];
    }
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            if (unique_arr[j] > unique_arr[j + 1]) {
                int tmp = unique_arr[j];
                unique_arr[j] = unique_arr[j + 1];
                unique_arr[j + 1] = tmp;
            }
        }
    }
    int u = 0;
    for (int i = 0; i < n; i++) {
        if (i == 0 || unique_arr[i] != unique_arr[i - 1]) {
            unique_arr[u++] = unique_arr[i];
        }
    }
    return u;
}

int cp_compressed_rank(const int* unique_arr, int size, int val) {
    int low = 0, high = size - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (unique_arr[mid] == val) return mid;
        if (unique_arr[mid] < val) low = mid + 1;
        else high = mid - 1;
    }
    return -1;
}

int cp_bit_count_set(unsigned int n) {
    int count = 0;
    while (n > 0) {
        n &= (n - 1);
        count++;
    }
    return count;
}

int cp_bit_iterate_submasks(int mask, int* out_submasks, int max_capacity) {
    int count = 0;
    for (int sub = mask; sub > 0; sub = (sub - 1) & mask) {
        if (count < max_capacity) {
            out_submasks[count++] = sub;
        }
    }
    return count;
}

int cp_bitmask_has_subset(int supermask, int submask) {
    return (supermask & submask) == submask;
}

void cp_sieve_eratosthenes(int n, char* is_prime) {
    for (int i = 0; i <= n; i++) is_prime[i] = 1;
    is_prime[0] = 0;
    if (n >= 1) is_prime[1] = 0;
    for (int p = 2; p * p <= n; p++) {
        if (is_prime[p]) {
            for (int i = p * p; i <= n; i += p) {
                is_prime[i] = 0;
            }
        }
    }
}

int cp_prime_factorization(long long n, long long* primes, int* exponents) {
    int count = 0;
    for (long long d = 2; d * d <= n; d++) {
        if (n % d == 0) {
            primes[count] = d;
            exponents[count] = 0;
            while (n % d == 0) {
                exponents[count]++;
                n /= d;
            }
            count++;
        }
    }
    if (n > 1) {
        primes[count] = n;
        exponents[count] = 1;
        count++;
    }
    return count;
}

long long cp_mod_pow(long long base, long long exp, long long mod) {
    long long res = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return res;
}

long long cp_extended_gcd(long long a, long long b, long long* x, long long* y) {
    if (b == 0) {
        *x = 1;
        *y = 0;
        return a;
    }
    long long x1, y1;
    long long gcd = cp_extended_gcd(b, a % b, &x1, &y1);
    *x = y1;
    *y = x1 - (a / b) * y1;
    return gcd;
}

long long cp_mod_inverse(long long a, long long mod) {
    long long x, y;
    long long g = cp_extended_gcd(a, mod, &x, &y);
    if (g != 1) return -1;
    return (x % mod + mod) % mod;
}

void cp_precompute_factorials(int n, long long mod, long long* fact, long long* inv_fact) {
    fact[0] = 1;
    for (int i = 1; i <= n; i++) {
        fact[i] = (fact[i - 1] * i) % mod;
    }
    inv_fact[n] = cp_mod_pow(fact[n], mod - 2, mod);
    for (int i = n - 1; i >= 0; i--) {
        inv_fact[i] = (inv_fact[i + 1] * (i + 1)) % mod;
    }
}

long long cp_ncr_modulo(int n, int r, long long mod, const long long* fact, const long long* inv_fact) {
    if (r < 0 || r > n) return 0;
    long long num = fact[n];
    long long den = (inv_fact[r] * inv_fact[n - r]) % mod;
    return (num * den) % mod;
}

void cp_matrix_multiply_2x2(const long long A[2][2], const long long B[2][2], long long C[2][2], long long mod) {
    long long r00 = (A[0][0] * B[0][0] + A[0][1] * B[1][0]) % mod;
    long long r01 = (A[0][0] * B[0][1] + A[0][1] * B[1][1]) % mod;
    long long r10 = (A[1][0] * B[0][0] + A[1][1] * B[1][0]) % mod;
    long long r11 = (A[1][0] * B[0][1] + A[1][1] * B[1][1]) % mod;
    C[0][0] = r00;
    C[0][1] = r01;
    C[1][0] = r10;
    C[1][1] = r11;
}

long long cp_matrix_power_fibonacci(long long n, long long mod) {
    if (n <= 0) return 0;
    if (n == 1) return 1;
    long long res[2][2] = {{1, 0}, {0, 1}};
    long long base[2][2] = {{1, 1}, {1, 0}};
    long long p = n - 1;
    while (p > 0) {
        if (p & 1) {
            long long tmp[2][2];
            cp_matrix_multiply_2x2(res, base, tmp, mod);
            res[0][0] = tmp[0][0]; res[0][1] = tmp[0][1];
            res[1][0] = tmp[1][0]; res[1][1] = tmp[1][1];
        }
        long long tmp_base[2][2];
        cp_matrix_multiply_2x2(base, base, tmp_base, mod);
        base[0][0] = tmp_base[0][0]; base[0][1] = tmp_base[0][1];
        base[1][0] = tmp_base[1][0]; base[1][1] = tmp_base[1][1];
        p >>= 1;
    }
    return res[0][0];
}

void cp_prefix_sum_1d_build(const int* arr, int n, long long* pref) {
    pref[0] = 0;
    for (int i = 0; i < n; i++) {
        pref[i + 1] = pref[i] + arr[i];
    }
}

long long cp_prefix_sum_1d_query(const long long* pref, int L, int R) {
    return pref[R + 1] - pref[L];
}

long long cp_prefix_sum_2d_query(const long long* pref, int cols_stride, int r1, int c1, int r2, int c2) {
    long long total = pref[(r2 + 1) * cols_stride + (c2 + 1)];
    long long top = pref[r1 * cols_stride + (c2 + 1)];
    long long left = pref[(r2 + 1) * cols_stride + c1];
    long long diag = pref[r1 * cols_stride + c1];
    return total - top - left + diag;
}

void cp_difference_array_range_add(long long* diff, int L, int R, long long val) {
    diff[L] += val;
    diff[R + 1] -= val;
}

void cp_difference_array_compute(const long long* diff, int n, long long* res) {
