void sieve(int n, char* is_prime) {
    for (int i = 0; i <= n; i++) is_prime[i] = 1;
    is_prime[0] = 0;
    if (n >= 1) is_prime[1] = 0;
    for (int p = 2; p * p <= n; p++) {
        if (is_prime[p]) {
            for (int i = p * p; i <= n; i += p) {
                is_prime[i] = 0;
            }
        }
    }
}

int factorize(long long n, long long* primes, int* exponents) {
    int count = 0;
    for (long long d = 2; d * d <= n; d++) {
        if (n % d == 0) {
            primes[count] = d;
            exponents[count] = 0;
            while (n % d == 0) {
                exponents[count]++;
                n /= d;
            }
            count++;
        }
    }
    if (n > 1) {
        primes[count] = n;
        exponents[count] = 1;
        count++;
    }
    return count;
}

int main(void) {
    char prime_flags[51];
    sieve(50, prime_flags);
    printf("Primes <= 50:\n");
    for (int i = 2; i <= 50; i++) {
        if (prime_flags[i]) printf("%d ", i);
    }
    printf("\n");
    long long p[10];
    int exp[10];
    int k = factorize(360, p, exp);
    printf("Prime factors of 360:\n");
    for (int i = 0; i < k; i++) {
        printf("%lld^%d ", p[i], exp[i]);
    }
    printf("\n");
    return 0;
}

#include <stdio.h>

long long mod_pow(long long base, long long exp, long long mod) {
    long long res = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return res;
}

long long ext_gcd(long long a, long long b, long long* x, long long* y) {
    if (b == 0) {
        *x = 1;
        *y = 0;
        return a;
    }
    long long x1, y1;
    long long g = ext_gcd(b, a % b, &x1, &y1);
    *x = y1;
    *y = x1 - (a / b) * y1;
    return g;
}

long long mod_inv(long long a, long long mod) {
    long long x, y;
    long long g = ext_gcd(a, mod, &x, &y);
    if (g != 1) return -1;
    return (x % mod + mod) % mod;
}

int main(void) {
    long long mod = 1000000007LL;
    long long p = mod_pow(3, 10, mod);
    long long inv = mod_inv(3, mod);
    printf("3^10 mod 1e9+7 = %lld\n", p);
    printf("inv(3) mod 1e9+7 = %lld\n", inv);
    printf("(3 * inv) mod 1e9+7 = %lld\n", (3 * inv) % mod);
    return 0;
}

