    printf("10C3 mod 1e9+7 = %lld\n", ncr(10, 3, mod, fact, inv_fact));
    printf("50C5 mod 1e9+7 = %lld\n", ncr(50, 5, mod, fact, inv_fact));
    return 0;
}

