#include <stdio.h>

int pair_sum(const int* arr, int n, int target, int* out_i, int* out_j) {
    int left = 0, right = n - 1;
    while (left < right) {
        int sum = arr[left] + arr[right];
        if (sum == target) {
            *out_i = left;
            *out_j = right;
            return 1;
        }
        if (sum < target) left++;
        else right--;
    }
    return 0;
}

long long trap_water(const int* h, int n) {
    if (n <= 2) return 0;
    int left = 0, right = n - 1;
    int left_max = 0, right_max = 0;
    long long water = 0;
    while (left <= right) {
        if (h[left] <= h[right]) {
            if (h[left] >= left_max) left_max = h[left];
            else water += (left_max - h[left]);
            left++;
        } else {
            if (h[right] >= right_max) right_max = h[right];
            else water += (right_max - h[right]);
            right--;
        }
    }
    return water;
}

int main(void) {
    int arr[] = {2, 4, 7, 11, 15};
    int i, j;
    if (pair_sum(arr, 5, 15, &i, &j)) {
        printf("Pair sum 15 found at indices %d and %d\n", i, j);
    }
    int heights[] = {0, 1, 0, 2, 1, 0, 1, 3, 2, 1, 2, 1};
    printf("Trapped water: %lld\n", trap_water(heights, 12));
    return 0;
}

#include <stdio.h>

long long max_fixed_window(const int* arr, int n, int k) {
    if (n < k || k <= 0) return 0;
    long long cur = 0;
    for (int i = 0; i < k; i++) cur += arr[i];
    long long max_sum = cur;
    for (int i = k; i < n; i++) {
        cur += arr[i] - arr[i - k];
        if (cur > max_sum) max_sum = cur;
    }
    return max_sum;
}

int min_len_subarray(const int* arr, int n, long long target) {
    int min_len = n + 1;
    long long cur = 0;
    int left = 0;
    for (int right = 0; right < n; right++) {
        cur += arr[right];
        while (cur >= target) {
            int len = right - left + 1;
            if (len < min_len) min_len = len;
            cur -= arr[left++];
        }
    }
    return (min_len <= n) ? min_len : 0;
}

int main(void) {
    int arr[] = {2, 3, 1, 2, 4, 3};
    int n = 6;
    printf("Max sum of window 3: %lld\n", max_fixed_window(arr, n, 3));
    printf("Min len for sum >= 7: %d\n", min_len_subarray(arr, n, 7));
    return 0;
}

#include <stdio.h>

void fenwick_update(long long* tree, int n, int idx, long long delta) {
    while (idx <= n) {
        tree[idx] += delta;
        idx += (idx & (-idx));
    }
}

long long fenwick_query(const long long* tree, int idx) {
    long long sum = 0;
    while (idx > 0) {
        sum += tree[idx];
        idx -= (idx & (-idx));
    }
    return sum;
}

