void next_greater(const int* arr, int n, int* res) {
    int stack[n];
    int top = -1;
    for (int i = 0; i < n; i++) res[i] = -1;
    for (int i = 0; i < n; i++) {
        while (top >= 0 && arr[i] > arr[stack[top]]) {
            res[stack[top--]] = arr[i];
        }
        stack[++top] = i;
    }
}

