#include <stdio.h>

void build_up(int n, int max_log, const int* parent, int* up) {
    for (int i = 0; i < n; i++) up[i * max_log + 0] = parent[i];
    for (int j = 1; j < max_log; j++) {
        for (int i = 0; i < n; i++) {
            int p = up[i * max_log + (j - 1)];
            if (p != -1) up[i * max_log + j] = up[p * max_log + (j - 1)];
            else up[i * max_log + j] = -1;
        }
    }
}

int query_lca(int u, int v, int max_log, const int* depth, const int* up) {
    if (depth[u] < depth[v]) {
        int tmp = u; u = v; v = tmp;
    }
    for (int j = max_log - 1; j >= 0; j--) {
        if (depth[u] - (1 << j) >= depth[v]) {
            u = up[u * max_log + j];
        }
    }
    if (u == v) return u;
    for (int j = max_log - 1; j >= 0; j--) {
        if (up[u * max_log + j] != up[v * max_log + j]) {
            u = up[u * max_log + j];
            v = up[v * max_log + j];
        }
    }
    return up[u * max_log + 0];
}

int main(void) {
    int n = 7, max_log = 4;
    int parent[] = {-1, 0, 0, 1, 1, 2, 2};
    int depth[]  = { 0, 1, 1, 2, 2, 2, 2};
    int up[7 * 4];
    build_up(n, max_log, parent, up);
    printf("LCA(3, 4) = %d\n", query_lca(3, 4, max_log, depth, up));
    printf("LCA(3, 5) = %d\n", query_lca(3, 5, max_log, depth, up));
    printf("LCA(4, 1) = %d\n", query_lca(4, 1, max_log, depth, up));
    return 0;
}

#include <stdio.h>

void tarjan(int u, const int* head, const int* to, const int* next, int* disc, int* low, int* in_stack, int* stack, int* top, int* timer, int* scc_id, int* scc_count) {
    disc[u] = low[u] = ++(*timer);
    stack[++(*top)] = u;
    in_stack[u] = 1;
    for (int e = head[u]; e != -1; e = next[e]) {
        int v = to[e];
        if (disc[v] == 0) {
            tarjan(v, head, to, next, disc, low, in_stack, stack, top, timer, scc_id, scc_count);
            if (low[v] < low[u]) low[u] = low[v];
        } else if (in_stack[v]) {
            if (disc[v] < low[u]) low[u] = disc[v];
        }
    }
    if (low[u] == disc[u]) {
        (*scc_count)++;
        while (1) {
            int node = stack[(*top)--];
            in_stack[node] = 0;
            scc_id[node] = *scc_count;
            if (node == u) break;
        }
    }
}

int main(void) {
    int n = 5;
    int head[5] = {0, 1, 2, 4, -1};
    int to[] = {1, 2, 0, 3, 4};
    int next[] = {-1, -1, 3, -1, -1};
    int disc[5] = {0}, low[5] = {0}, in_stack[5] = {0}, stack[5];
    int top = -1, timer = 0, scc_id[5] = {0}, scc_count = 0;

    for (int i = 0; i < n; i++) {
        if (disc[i] == 0) {
            tarjan(i, head, to, next, disc, low, in_stack, stack, &top, &timer, scc_id, &scc_count);
        }
    }
    printf("Total SCCs: %d\n", scc_count);
    for (int i = 0; i < n; i++) {
        printf("Node %d in SCC %d\n", i, scc_id[i]);
    }
    return 0;
}

