double solve_bisection(double a, double b, double tol, int max_iter) {
    if (f(a) * f(b) >= 0) {
        printf("Invalid bracket: f(a) and f(b) must have opposite signs\n");
        return a;
    }
    double c = a;
    for (int i = 0; i < max_iter; i++) {
        c = (a + b) / 2.0;
        if (fabs(f(c)) < tol || (b - a) / 2.0 < tol) break;
        if (f(c) * f(a) < 0) b = c;
        else a = c;
    }
    return c;
}

