#include <stdio.h>
#include <math.h>

void solve_gauss_jordan(int n, double a[n][n + 1], double x[n]) {
    for (int i = 0; i < n; i++) {
        int max_row = i;
        double max_val = fabs(a[i][i]);
        for (int k = i + 1; k < n; k++) {
            if (fabs(a[k][i]) > max_val) {
                max_val = fabs(a[k][i]);
                max_row = k;
            }
        }
        for (int j = 0; j <= n; j++) {
            double tmp = a[i][j];
            a[i][j] = a[max_row][j];
            a[max_row][j] = tmp;
        }
        double pivot = a[i][i];
        for (int j = 0; j <= n; j++) {
            a[i][j] /= pivot;
        }
        for (int k = 0; k < n; k++) {
            if (k != i) {
                double factor = a[k][i];
                for (int j = 0; j <= n; j++) {
                    a[k][j] -= factor * a[i][j];
                }
            }
        }
    }
    for (int i = 0; i < n; i++) {
        x[i] = a[i][n];
    }
}

