        double max_err = 0.0;
        for (int i = 0; i < n; i++) {
            double sum = b[i];
            for (int j = 0; j < n; j++) {
                if (j != i) sum -= A[i][j] * x[j];
            }
            double new_val = sum / A[i][i];
            double err = fabs(new_val - x[i]);
            if (err > max_err) max_err = err;
            x[i] = new_val;
        }
        if (max_err < tol) break;
    }
}

