double simpson_one_third(double a, double b, int n) {
    if (n % 2 != 0) n++;
    double h = (b - a) / n;
    double sum = f(a) + f(b);
    for (int i = 1; i < n; i++) {
        double x = a + i * h;
        sum += (i % 2 != 0) ? 4.0 * f(x) : 2.0 * f(x);
    }
    return (sum * h) / 3.0;
}

double simpson_three_eighth(double a, double b, int n) {
    while (n % 3 != 0) n++;
    double h = (b - a) / n;
    double sum = f(a) + f(b);
    for (int i = 1; i < n; i++) {
        double x = a + i * h;
        sum += (i % 3 == 0) ? 2.0 * f(x) : 3.0 * f(x);
    }
    return (3.0 * h * sum) / 8.0;
}

