    double a = 0.0, b = 2.0;
    printf("Simpson 1/3 Integral of e^x: %.6f\n", simpson_one_third(a, b, 10));
    printf("Simpson 3/8 Integral of e^x: %.6f\n", simpson_three_eighth(a, b, 12));
