    print_account(&a1);
    print_account(&a2);
    deposit(&a1, 250.0);
    withdraw(&a2, 100.0);
    transfer(&a2, &a1, 300.0);
    printf("\nFinal Accounts after transactions:\n");
    print_account(&a1);
    print_account(&a2);
    return 0;
}

