    char title[40];
    char author[32];
    int available;
    int total;
} Book;

int borrow_book(Book* b) {
    if (b->available > 0) {
        b->available--;
        return 1;
    }
    return 0;
}

int return_book(Book* b) {
    if (b->available < b->total) {
        b->available++;
        return 1;
    }
    return 0;
}

void print_book(const Book* b) {
    printf("[%d] '%s' by %s (%d/%d available)\n", b->id, b->title, b->author, b->available, b->total);
}

