#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int eval_lisp(const char** expr) {
    while (**expr == ' ' || **expr == '(') (*expr)++;
    char op = **expr;
    (*expr)++;
    while (**expr == ' ') (*expr)++;
    int res = (op == '*') ? 1 : 0;
    int first = 1;
    while (**expr && **expr != ')') {
        while (**expr == ' ') (*expr)++;
        if (**expr == ')') break;
        int val;
        if (**expr == '(') {
            val = eval_lisp(expr);
        } else {
            val = strtol(*expr, (char**)expr, 10);
        }
        if (op == '+') res += val;
        else if (op == '*') res *= val;
        else if (op == '-') {
            if (first) res = val;
            else res -= val;
        }
        first = 0;
    }
    if (**expr == ')') (*expr)++;
    return res;
}

int main(void) {
    const char* code = "(+ 2 (* 3 4) 5)";
    const char* ptr = code;
    printf("Eval '%s' = %d\n", code, eval_lisp(&ptr));
    return 0;
}

